import uuid

import pytest

from bedrock_protocol import v1001, v2168, v2225

HANDLE = v2225.WaypointGroup.WaypointHandle
PAYLOAD = v2225.ServerWaypoint.Payload
ACTION = v2225.ServerWaypointGroup.Action

